#' Campionamento casuale semplice
#'
#' 
#' @param data .
#' @param id_var Variabile usata per identificare le singole unità nel
#'   dataset. Se specificata, la tabella "Unità estratte" mostra gli ID dei
#'   soggetti selezionati. Non influisce sul processo di estrazione.
#' @param tuto Se TRUE mostra il pannello con la descrizione metodologica.
#' @param replacement Se TRUE estrazione con reinserimento (SCR): la stessa
#'   unità può essere selezionata più volte. Se FALSE estrazione senza
#'   reinserimento (SSR).
#' @param size_mode Indica se il campione è definito tramite un numero
#'   assoluto di unità (n) oppure tramite una frazione f = n/N della
#'   popolazione.
#' @param n Numerosità del campione da estrarre.
#' @param f Frazione f = n/N della popolazione da estrarre (es. 0.1 = 10\%).
#' @param seed Seme del generatore casuale. Impostare un valore garantisce
#'   l'esatta riproducibilità del campione.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$extracted} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$out_freq} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
samplesimple <- function(
    data,
    id_var,
    tuto = TRUE,
    replacement = FALSE,
    size_mode = "n",
    n = 30,
    f = 0.1,
    seed = 1) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("samplesimple requires jmvcore to be installed (restart may be required)")

    if ( ! missing(id_var)) id_var <- jmvcore::resolveQuo(jmvcore::enquo(id_var))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(id_var), id_var, NULL))


    options <- samplesimpleOptions$new(
        id_var = id_var,
        tuto = tuto,
        replacement = replacement,
        size_mode = size_mode,
        n = n,
        f = f,
        seed = seed)

    analysis <- samplesimpleClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

